-- ============================================
-- LUMA — Oz Tome 5 : Chapitres XVIII-XX (Départ vers le Sud, la forêt des arbres combattants, le pays de porcelaine)
-- Texte original, domaine public
-- ============================================


with s as (select id from books where title = 'The Wonderful Wizard of Oz' and is_series = true),
     lang as (select id from languages where code = 'en')
insert into books (language_id, title, theme, description, cecr_level, cover_emoji, total_pages, position, series_id, volume_number)
select lang.id, 'Tome 5 : Vers le pays du Sud', 'Classique • L. Frank Baum (1900)', 'Dorothy et ses amis quittent la Cité d''Émeraude pour trouver Glinda, affrontent une forêt d''arbres combattants, et traversent un fragile pays entièrement fait de porcelaine.', 'B1', '🏺', 3, 1, s.id, 5
from lang, s;


with b as (select id from books where title = 'Tome 5 : Vers le pays du Sud' and series_id = (select id from books where title = 'The Wonderful Wizard of Oz' and is_series = true))
insert into book_pages (book_id, page_number, sentences)
select b.id, 1, '[{"en": "Dorothy wept bitterly at the passing of her hope to get home. The Scarecrow was now the ruler of the Emerald City, and though he was not a Wizard, the people were proud of him.", "fr": "Dorothy pleura amèrement en voyant son espoir de rentrer chez elle s''envoler. L''Épouvantail était maintenant le dirigeant de la Cité d''Émeraude, et bien qu''il ne soit pas un magicien, le peuple était fier de lui."}, {"en": "''Why not call the Winged Monkeys, and ask them to carry you over the desert?'' suggested the Scarecrow. But the Monkey King shook his head: ''That cannot be done. We belong to this country alone, and cannot leave it.''", "fr": "''Pourquoi ne pas appeler les Singes Ailés, et leur demander de vous porter au-dessus du désert ?'' suggéra l''Épouvantail. Mais le Roi des Singes secoua la tête : ''Ça ne peut pas se faire. Nous appartenons uniquement à ce pays, et ne pouvons le quitter.''"}, {"en": "The soldier with the green whiskers suggested Glinda, the Witch of the South, who ruled the Quadlings from her castle at the edge of the desert. ''It seems the best thing Dorothy can do is to travel to the Land of the South and ask Glinda to help her,'' said the Scarecrow.", "fr": "Le soldat aux favoris verts suggéra Glinda, la Sorcière du Sud, qui régnait sur les Quadlings depuis son château à la lisière du désert. ''Il semble que la meilleure chose que Dorothy puisse faire est de voyager vers le pays du Sud et de demander l''aide de Glinda,'' dit l''Épouvantail."}, {"en": "''I shall go with Dorothy,'' declared the Lion, ''for I am tired of your city and long for the woods again.'' ''My axe may be of service to her; so I also will go,'' agreed the Woodman.", "fr": "''J''irai avec Dorothy,'' déclara le Lion, ''car je suis fatigué de votre ville et j''aspire à retrouver les bois.'' ''Ma hache pourrait lui être utile ; donc j''irai aussi,'' accepta l''Homme de Fer-Blanc."}, {"en": "''If it wasn''t for Dorothy I should never have had brains,'' said the Scarecrow. ''So my good luck is all due to her, and I shall never leave her until she starts back to Kansas for good and all.''", "fr": "''Si ce n''était pas pour Dorothy je n''aurais jamais eu de cervelle,'' dit l''Épouvantail. ''Donc ma bonne fortune lui est entièrement due, et je ne la quitterai jamais jusqu''à ce qu''elle retourne au Kansas pour de bon.''"}, {"en": "''We shall go tomorrow morning,'' the Scarecrow decided, and so it was settled. All four would journey together toward the Land of the South.", "fr": "''Nous partirons demain matin,'' décida l''Épouvantail, et ainsi ce fut décidé. Tous les quatre voyageraient ensemble vers le pays du Sud."}]'::jsonb from b;


with b as (select id from books where title = 'Tome 5 : Vers le pays du Sud' and series_id = (select id from books where title = 'The Wonderful Wizard of Oz' and is_series = true))
insert into book_pages (book_id, page_number, sentences)
select b.id, 2, '[{"en": "The Guardian of the Gates wished them well as they set off. ''City life does not agree with me at all,'' remarked the Lion happily, sniffing the fresh country air.", "fr": "Le Gardien des Portes leur souhaita bonne chance alors qu''ils partaient. ''La vie citadine ne me convient pas du tout,'' remarqua le Lion joyeusement, en humant l''air frais de la campagne."}, {"en": "''Oz was not such a bad Wizard, after all,'' said the Tin Woodman. Dorothy said nothing—Oz had not kept his promise to her, but he had done his best, so she forgave him.", "fr": "''Oz n''était pas un si mauvais magicien, après tout,'' dit l''Homme de Fer-Blanc. Dorothy ne dit rien—Oz n''avait pas tenu sa promesse envers elle, mais il avait fait de son mieux, alors elle lui pardonna."}, {"en": "They came to a thick wood where the first row of trees suddenly bent their branches and flung the Scarecrow headlong back among his friends. ''The trees seem to have made up their minds to fight us,'' remarked the Lion.", "fr": "Ils arrivèrent à un bois épais où la première rangée d''arbres plia soudainement ses branches et projeta l''Épouvantail en arrière parmi ses amis. ''Les arbres semblent avoir décidé de nous combattre,'' remarqua le Lion."}, {"en": "''I believe I will try it myself,'' said the Woodman, and when a branch bent to seize him, he chopped it fiercely in two. The tree shook all its branches as if in pain, and the Woodman passed safely under it.", "fr": "''Je crois que je vais essayer moi-même,'' dit l''Homme de Fer-Blanc, et quand une branche se pencha pour le saisir, il la coupa férocement en deux. L''arbre secoua toutes ses branches comme s''il avait mal, et l''Homme de Fer-Blanc passa en sécurité en dessous."}, {"en": "''Come on! Be quick!'' he shouted, and they all ran forward safely, except Toto who was caught by a small branch until the Woodman chopped it free.", "fr": "''Venez ! Vite !'' cria-t-il, et ils coururent tous en avant en sécurité, sauf Toto qui fut attrapé par une petite branche jusqu''à ce que l''Homme de Fer-Blanc la coupe pour le libérer."}, {"en": "On the far side of the wood, they found before them a high wall that seemed to be made of smooth white china. ''I will make a ladder,'' said the Tin Woodman, ''for we certainly must climb over the wall.''", "fr": "De l''autre côté du bois, ils trouvèrent devant eux un haut mur qui semblait être fait de porcelaine blanche et lisse. ''Je vais faire une échelle,'' dit l''Homme de Fer-Blanc, ''car nous devons certainement escalader ce mur.''"}]'::jsonb from b;


with b as (select id from books where title = 'Tome 5 : Vers le pays du Sud' and series_id = (select id from books where title = 'The Wonderful Wizard of Oz' and is_series = true))
insert into book_pages (book_id, page_number, sentences)
select b.id, 3, '[{"en": "Climbing the finished ladder, they each cried ''Oh, my!'' as they looked over into a strange country with a floor as smooth and white as a platter, dotted with tiny china houses, animals, and people.", "fr": "En grimpant l''échelle terminée, ils s''écrièrent chacun ''Oh là là !'' en regardant vers un pays étrange avec un sol lisse et blanc comme un plat, parsemé de minuscules maisons, animaux et personnes en porcelaine."}, {"en": "They climbed down carefully, patted the Scarecrow back into shape, and began walking through the china country. A china cow suddenly kicked over a milkmaid and broke her own leg off with a great clatter.", "fr": "Ils descendirent avec précaution, remirent l''Épouvantail en forme, et commencèrent à marcher à travers le pays de porcelaine. Une vache en porcelaine renversa soudainement une laitière et cassa sa propre jambe dans un grand fracas."}, {"en": "''What do you mean by coming here and frightening my cow?'' cried the milkmaid angrily, leading her limping cow away. ''We must be very careful here,'' said the kind-hearted Woodman, ''or we may hurt these pretty little people.''", "fr": "''Qu''est-ce qui vous prend de venir ici effrayer ma vache ?'' cria la laitière avec colère, emmenant sa vache boiteuse. ''Nous devons être très prudents ici,'' dit l''Homme de Fer-Blanc au grand cœur, ''ou nous pourrions blesser ces jolis petits êtres.''"}, {"en": "Dorothy met a beautiful china Princess who refused to be carried away. ''That would make me very unhappy,'' the Princess explained. ''Whenever any of us are taken away our joints at once stiffen, and we can only stand straight and look pretty.''", "fr": "Dorothy rencontra une belle Princesse en porcelaine qui refusa d''être emportée. ''Cela me rendrait très malheureuse,'' expliqua la Princesse. ''Chaque fois que l''un de nous est emmené, nos articulations se raidissent aussitôt, et nous pouvons seulement rester droits et avoir l''air jolis.''"}, {"en": "A jolly cracked clown named Mr. Joker, mended in a hundred places from his constant tumbling, recited a silly rhyme before standing on his head. ''I would not make you unhappy for all the world!'' said Dorothy, bidding the Princess farewell.", "fr": "Un joyeux clown fêlé nommé M. Farceur, rafistolé à cent endroits à force de tomber sans cesse, récita une comptine loufoque avant de se tenir sur la tête. ''Je ne voudrais pas te rendre malheureuse pour rien au monde !'' dit Dorothy, faisant ses adieux à la Princesse."}, {"en": "At the far wall, the Lion jumped up and accidentally smashed a tiny china church with his tail. ''There are worse things in the world than being a Scarecrow,'' the Scarecrow observed, glad he could not be so easily broken.", "fr": "Au mur opposé, le Lion sauta et fracassa accidentellement une petite église en porcelaine avec sa queue. ''Il y a de pires choses au monde qu''être un Épouvantail,'' observa l''Épouvantail, content de ne pas pouvoir se casser aussi facilement."}]'::jsonb from b;
